package com.nigson.acceptance.fulfillment;
import com.nigson.commerce.fulfillment.*;
import com.nigson.commerce.inventory.StockLedger;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.time.*;
import static org.assertj.core.api.Assertions.*;
class ShipmentPersistenceTest {
 ShipmentFixture f;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"fulfillment-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");f=new ShipmentFixture(new JdbcTemplate(ds),new DataSourceTransactionManager(ds));}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 @Test void fedexCreationPersistsIntentAndNeverDispatchesBeforePrivateBookedProof(){var shipment=f.create("5","FEDEX",null,"fedex");assertThat(shipment.status()).isEqualTo("CREATED");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,shipment.id())).isEqualTo(2);assertThat(f.service.create(f.inventory.actor,f.order,f.input("5","FEDEX",null),"fedex",UUID.randomUUID())).isEqualTo(shipment);assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","dispatch",UUID.randomUUID())).hasMessage("INVALID_TRANSITION");assertThatThrownBy(()->f.create("1","FEDEX",null,"overclaim")).hasMessage("FULFILLMENT_RULE_VIOLATION");}
 @Test void manualContingencyDispatchAndDeliveryConserveStockExactlyOnce(){var shipment=f.create("5","MANUAL","SYNTH_RECEIPT_"+UUID.randomUUID(),"manual");assertThat(shipment.status()).isEqualTo("READY");var shipped=f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","dispatch",UUID.randomUUID());assertThat(shipped.status()).isEqualTo("SHIPPED");assertThat(f.value("on_hand")).isEqualByComparingTo("5");assertThat(f.value("allocated")).isZero();assertThat(f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","dispatch",UUID.randomUUID())).isEqualTo(shipped);assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","new-stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");var input=new FulfillmentValues.Delivery(Instant.now(),"Synthetic actual delivery receipt");var delivered=f.service.delivered(f.inventory.actor,shipment.id(),1,input,"delivered",UUID.randomUUID());assertThat(delivered.status()).isEqualTo("DELIVERED");assertThat(f.inventory.jdbc.queryForObject("SELECT status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("DELIVERED");assertThat(f.inventory.jdbc.queryForObject("SELECT payment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PAID");assertThat(f.value("on_hand")).isEqualByComparingTo("5");}
 @Test void physicalReceiptAcrossDifferentKeysRestoresStockOnceAndDoesNotRefundMoney(){var shipment=f.create("5","MANUAL","SYNTH_RECEIPT_"+UUID.randomUUID(),"manual");f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","dispatch",UUID.randomUUID());var input=new FulfillmentValues.ReturnInput(List.of(new FulfillmentValues.LineInput(f.line,f.balance,"2")),StockLedger.ReturnKind.PHYSICAL_RETURN,"SYNTHETIC_PHYSICAL_RECEIPT","Synthetic verified physical return");var returned=f.service.returned(f.inventory.actor,f.order,input,"first-return",UUID.randomUUID());assertThat(f.value("on_hand")).isEqualByComparingTo("7");assertThat(f.service.returned(f.inventory.actor,f.order,input,"second-key-same-receipt",UUID.randomUUID())).isEqualTo(returned);assertThat(f.value("on_hand")).isEqualByComparingTo("7");assertThat(f.inventory.jdbc.queryForObject("SELECT payment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PAID");assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='STOCK_RETURN'",Integer.class,f.order)).isEqualTo(1);}
 @Test void unshippedCancellationReleasesAllocationAndAuditFaultRollsBackDispatch(){var shipment=f.create("5","MANUAL","SYNTH_RECEIPT_"+UUID.randomUUID(),"manual");f.inventory.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","audit-dispatch",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.repository.find(shipment.id(),false).status()).isEqualTo("READY");assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isEqualByComparingTo("5");}finally{f.inventory.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}f.inventory.jdbc.update("UPDATE commerce.sales_order SET status='REFUNDING' WHERE id=?",f.order);var input=new FulfillmentValues.ReturnInput(List.of(new FulfillmentValues.LineInput(f.line,f.balance,"5")),StockLedger.ReturnKind.UNSHIPPED_CANCEL,null,"Synthetic authorized unshipped reversal");f.service.returned(f.inventory.actor,f.order,input,"unshipped",UUID.randomUUID());assertThat(f.value("on_hand")).isEqualByComparingTo("10");assertThat(f.value("allocated")).isZero();assertThat(f.inventory.jdbc.queryForObject("SELECT payment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PAID");}
 @Test void partialShipmentsDeliverOrderOnlyWhenAllEligibleQuantityArrives(){var first=f.create("2","MANUAL","SYNTH_RECEIPT_"+UUID.randomUUID(),"first");var second=f.create("3","MANUAL","SYNTH_RECEIPT_"+UUID.randomUUID(),"second");f.service.dispatch(f.inventory.actor,first.id(),0,"Synthetic first physical handover","first-dispatch",UUID.randomUUID());assertThat(f.inventory.jdbc.queryForObject("SELECT fulfillment_status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PARTIALLY_SHIPPED");f.service.delivered(f.inventory.actor,first.id(),1,new FulfillmentValues.Delivery(Instant.now(),"Synthetic first delivery evidence"),"first-delivery",UUID.randomUUID());assertThat(f.inventory.jdbc.queryForObject("SELECT status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("PROCESSING");f.service.dispatch(f.inventory.actor,second.id(),0,"Synthetic second physical handover","second-dispatch",UUID.randomUUID());assertThat(f.inventory.jdbc.queryForObject("SELECT status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("SHIPPED");f.service.delivered(f.inventory.actor,second.id(),1,new FulfillmentValues.Delivery(Instant.now(),"Synthetic second delivery evidence"),"second-delivery",UUID.randomUUID());assertThat(f.inventory.jdbc.queryForObject("SELECT status FROM commerce.sales_order WHERE id=?",String.class,f.order)).isEqualTo("DELIVERED");assertThat(f.value("on_hand")).isEqualByComparingTo("5");}
 @Test void fedexLabelAndBookedEvidenceAreBothRequiredAndFinancialHoldPreventsDispatch(){var shipment=f.create("5","FEDEX",null,"fedex");f.inventory.jdbc.update("UPDATE commerce.shipment SET status='READY',provider_reference='SYNTHETIC_OFFLINE_BOOKING' WHERE id=?",shipment.id());assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","no-proof",UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");f.inventory.jdbc.update("INSERT INTO commerce.shipment_event(id,created_by,shipment_id,source,event_key,status,occurred_at) VALUES (?,'test',?,'FEDEX',?,'BOOKED',now())",UUID.randomUUID(),shipment.id(),UUID.randomUUID().toString());assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","no-label",UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");UUID label=UUID.randomUUID();f.inventory.jdbc.update("INSERT INTO commerce.asset_reference(id,created_by,updated_by,object_key,purpose,mime_type,byte_size,checksum_sha256,status,classification,shipment_id) VALUES (?,'test','test',?,'SHIPPING_LABEL','application/pdf',10,?,'CLEAN','PRIVATE',?)",label,"synthetic-private-label/"+label,"a".repeat(64),shipment.id());f.inventory.jdbc.update("UPDATE commerce.shipment SET label_asset_id=? WHERE id=?",label,shipment.id());f.inventory.jdbc.update("UPDATE commerce.sales_order SET hold_reason='Synthetic hold' WHERE id=?",f.order);assertThatThrownBy(()->f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","held",UUID.randomUUID())).hasMessage("FULFILLMENT_RULE_VIOLATION");f.inventory.jdbc.update("UPDATE commerce.sales_order SET hold_reason=NULL WHERE id=?",f.order);assertThat(f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","booked",UUID.randomUUID()).status()).isEqualTo("SHIPPED");}
 @Test void racingShipmentClaimsCannotExceedOneAllocatedOrder()throws Exception{try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var work=new ArrayList<java.util.concurrent.Future<Object>>();for(int n=0;n<2;n++){String key="claim-race-"+n;work.add(pool.submit(()->{start.await();try{return f.create("5","FEDEX",null,key);}catch(com.nigson.shared.problem.Problem.Failure|com.nigson.commerce.platform.PlatformStore.Conflict failure){return failure.getMessage();}}));}start.countDown();int accepted=0;for(var task:work){Object result=task.get(20,java.util.concurrent.TimeUnit.SECONDS);if(result instanceof FulfillmentValues.Shipment)accepted++;else assertThat(result).isIn("FULFILLMENT_RULE_VIOLATION","IDEMPOTENCY_IN_PROGRESS");}assertThat(accepted).isEqualTo(1);}assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.shipment WHERE order_id=?",Integer.class,f.order)).isEqualTo(1);}
 @Test void twelveDuplicateDispatchesHaveOneStockAndAuditEffect()throws Exception{var shipment=f.create("5","MANUAL","SYNTH_RECEIPT_"+UUID.randomUUID(),"manual");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(12)){var start=new java.util.concurrent.CountDownLatch(1);var work=new ArrayList<java.util.concurrent.Future<Object>>();for(int n=0;n<12;n++)work.add(pool.submit(()->{start.await();try{return f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","duplicate",UUID.randomUUID());}catch(com.nigson.shared.problem.Problem.Failure|com.nigson.commerce.platform.PlatformStore.Conflict failure){return failure.getMessage();}}));start.countDown();for(var task:work){Object result=task.get(20,java.util.concurrent.TimeUnit.SECONDS);if(result instanceof FulfillmentValues.Shipment s)assertThat(s.status()).isEqualTo("SHIPPED");else assertThat(result).isEqualTo("IDEMPOTENCY_IN_PROGRESS");}}assertThat(f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","duplicate",UUID.randomUUID()).status()).isEqualTo("SHIPPED");assertThat(f.value("on_hand")).isEqualByComparingTo("5");assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.inventory_movement WHERE order_id=? AND movement_type='DISPATCH'",Integer.class,f.order)).isEqualTo(1);assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='SHIPMENT_DISPATCH'",Integer.class,shipment.id())).isEqualTo(1);}
 @Test void receiptConflictingQuantityAndCurrentRoleRevocationDenyNewEffects(){var shipment=f.create("5","MANUAL","SYNTH_RECEIPT_"+UUID.randomUUID(),"manual");f.service.dispatch(f.inventory.actor,shipment.id(),0,"Synthetic physical handover proof","dispatch",UUID.randomUUID());var rows=List.of(new FulfillmentValues.LineInput(f.line,f.balance,"2"));var input=new FulfillmentValues.ReturnInput(rows,StockLedger.ReturnKind.PHYSICAL_RETURN,"SYNTHETIC_RECEIPT","Synthetic verified physical return");f.service.returned(f.inventory.actor,f.order,input,"return",UUID.randomUUID());var conflicting=new FulfillmentValues.ReturnInput(List.of(new FulfillmentValues.LineInput(f.line,f.balance,"3")),input.kind(),input.receiptReference(),input.reason());assertThatThrownBy(()->f.service.returned(f.inventory.actor,f.order,conflicting,"conflicting",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");f.inventory.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=? AND role='OPERATIONS'",f.inventory.actor.party());assertThatThrownBy(()->f.service.returned(f.inventory.actor,f.order,input,"return",UUID.randomUUID())).hasMessage("ACCESS_DENIED");assertThat(f.value("on_hand")).isEqualByComparingTo("7");}

 @Test void refundedAndUnshippedCancelledUnitsAreNotSubtractedTwice(){f.inventory.jdbc.update("UPDATE commerce.sales_order SET status='REFUNDING' WHERE id=?",f.order);f.service.returned(f.inventory.actor,f.order,new FulfillmentValues.ReturnInput(List.of(new FulfillmentValues.LineInput(f.line,f.balance,"2")),StockLedger.ReturnKind.UNSHIPPED_CANCEL,null,"Synthetic authorized unshipped reversal"),"cancel-two",UUID.randomUUID());UUID refund=UUID.randomUUID();UUID attempt=f.inventory.jdbc.queryForObject("SELECT id FROM commerce.payment_attempt WHERE order_id=?",UUID.class,f.order);f.inventory.jdbc.update("UPDATE commerce.sales_order SET subtotal=10,grand_total=10 WHERE id=?",f.order);f.inventory.admin.update("UPDATE commerce.order_line SET unit_amount=2,line_total=10 WHERE id=?",f.line);f.inventory.jdbc.update("UPDATE commerce.payment_attempt SET expected_amount=10 WHERE id=?",attempt);f.inventory.admin.update("UPDATE commerce.payment_transaction SET settled_amount=10 WHERE attempt_id=?",attempt);f.inventory.jdbc.update("INSERT INTO commerce.refund(id,created_by,updated_by,order_id,attempt_id,request_key,provider_reference,amount,currency_code,state,reason,requested_by,approved_by) VALUES (?,'test','test',?,?,?,?,4,'NGN','SUCCEEDED','Synthetic offline fixture refund',?,?)",refund,f.order,attempt,"SYNTH_"+refund,"SYNTH_"+refund,f.inventory.actor.party(),f.inventory.actor.party());f.inventory.jdbc.update("INSERT INTO commerce.refund_line(id,created_by,updated_by,refund_id,order_line_id,quantity,amount) VALUES (?,'test','test',?,?,2,4)",UUID.randomUUID(),refund,f.line);f.inventory.jdbc.update("UPDATE commerce.sales_order SET status='PAID' WHERE id=?",f.order);assertThatThrownBy(()->f.create("4","FEDEX",null,"over-net")).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(f.create("3","FEDEX",null,"remaining-three").lines().getFirst().quantity()).isEqualTo("3");assertThat(f.value("allocated")).isEqualByComparingTo("3");f.inventory.jdbc.update("DELETE FROM commerce.refund_line WHERE refund_id=?",refund);f.inventory.jdbc.update("DELETE FROM commerce.refund WHERE id=?",refund);}
 @Test void verifiedPaymentModeMustMatchFrozenCarrierMode(){f.inventory.jdbc.update("UPDATE commerce.payment_attempt SET provider_mode='LIVE' WHERE order_id=?",f.order);f.inventory.admin.update("UPDATE commerce.payment_transaction SET provider_mode='LIVE' WHERE attempt_id IN(SELECT id FROM commerce.payment_attempt WHERE order_id=?)",f.order);assertThatThrownBy(()->f.create("5","FEDEX",null,"wrong-payment-mode")).hasMessage("FULFILLMENT_RULE_VIOLATION");assertThat(f.inventory.jdbc.queryForObject("SELECT count(*) FROM commerce.shipment WHERE order_id=?",Integer.class,f.order)).isZero();}

}
